mapper.select:
select  from t_ai_chat_session s where 
and s.acs_id < #{before}
order by s.acs_id desc limit 21

select acm_id as id,case acm_role when 1 then 'user' else 'assistant' end as role,
    acm_content as content,case when acm_role=2 then right(acm_intent,1) else null end as state
from t_ai_chat_message where acm_session_id=#{sessionId} and acm_role in (1,2)
and acm_id < #{before}
order by acm_id desc limit #{limit}
